// Where the proof flow goes next. Typed routes are generated by the dev
// server from app/**, so links to routes other agents are still building
// (/weave/[id]) are built here as Href values in one place.
import type { Href } from "expo-router";
import type { ChapterId, DreamId, ProofId } from "@/contexts/arc.types";

/** The Weave interstitial (S1), which lands on the chapter. */
export function weaveHref(chapterId: ChapterId): Href {
  return `/weave/${encodeURIComponent(chapterId)}` as Href;
}

/** The reader. */
export function chapterHref(chapterId: ChapterId): Href {
  return { pathname: "/story/[id]", params: { id: chapterId } };
}

/** The proof form for a dream's open bridge. */
export function evidenceHref(dreamId: DreamId): Href {
  return { pathname: "/evidence/[intentId]", params: { intentId: dreamId } };
}

/**
 * The Star Birth (and, at the 7th star, the Named Sky) for a proof that is
 * already saved: NotTodaySheet hands over here, and a reload of the success
 * state lands here too.
 */
export function starBirthHref(dreamId: DreamId, proofId: ProofId): Href {
  return { pathname: "/evidence/[intentId]", params: { intentId: dreamId, born: proofId } };
}

export const TODAY_HREF: Href = "/";
